begin;
do $curate$ declare bid uuid; begin
if exists(select 1 from public.businesses where lower(name)=lower('Valley Pro Handyman') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') ~ '2096001073$' or lower(rtrim(website,'/'))=lower(rtrim('https://valleyprohandyman.net/','/'))) then raise exception 'Duplicate candidate requires review'; end if;
insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at)
values('Valley Pro Handyman','Home Services','Tracy','','(209) 600-1073','https://valleyprohandyman.net/','Tracy-based handyman business advertising small repairs, cabinet and door work, drywall repair, furniture assembly and property maintenance. Its service-area page includes Mountain House, Tracy, Lathrop and Manteca. The operator states it does not have a general contractor license. Confirm job scope and availability directly; an estimate request is available on its website.','approved',true,false,null,0,'editorial_first_party','https://valleyprohandyman.net/','first_party_website_desk_check',now()) returning id into bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Valley Pro Handyman", "city": "Tracy", "address": "", "phone": "(209) 600-1073", "website": "https://valleyprohandyman.net/", "description": "Tracy-based handyman business advertising small repairs, cabinet and door work, drywall repair, furniture assembly and property maintenance. Its service-area page includes Mountain House, Tracy, Lathrop and Manteca. The operator states it does not have a general contractor license. Confirm job scope and availability directly; an estimate request is available on its website.", "tags": ["handyman", "small repairs", "assembly", "home maintenance"], "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "note": "Primary homepage and estimate page confirm identity, Tracy base, public phone, advertised tasks and named service areas. Operator disclaimer retained; no independent license/insurance check, quality endorsement or availability claim. Residential address omitted. Sources https://valleyprohandyman.net/ and https://valleyprohandyman.net/estimate/."}'::jsonb,'Individually sourced relaunch addition; primary-site desk check only','https://valleyprohandyman.net/');
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://valleyprohandyman.net/',array['identity','public phone','website','advertised services','advertised service area'],array['Mountain House','Tracy','Lathrop','Manteca'],array['handyman','small repairs','assembly','home maintenance'],'First-party website desk check only. No owner confirmation, credential validation, availability check or quality endorsement. Primary homepage and estimate page confirm identity, Tracy base, public phone, advertised tasks and named service areas. Operator disclaimer retained; no independent license/insurance check, quality endorsement or availability claim. Residential address omitted. Sources https://valleyprohandyman.net/ and https://valleyprohandyman.net/estimate/.');
end $curate$;
