insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at)
values('Lara’s Cleaning','Home Services','Service area only','','(650) 391-7438','https://www.larascleaning.us/','Residential cleaning service advertising basic, deep, recurring and move-out cleaning, plus commercial cleaning. Its website names Mountain House, Tracy, Lathrop and Manteca in its service area. Call or use the website contact form to confirm the scope, price and scheduling for your property. An office location was not established.','approved',true,false,null,0,'editorial_first_party','https://www.larascleaning.us/','first_party_website_desk_check',now()) returning id into bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Lara\u2019s Cleaning", "city": "Service area only", "address": "", "phone": "(650) 391-7438", "website": "https://www.larascleaning.us/", "description": "Residential cleaning service advertising basic, deep, recurring and move-out cleaning, plus commercial cleaning. Its website names Mountain House, Tracy, Lathrop and Manteca in its service area. Call or use the website contact form to confirm the scope, price and scheduling for your property. An office location was not established.", "tags": ["house cleaning", "recurring cleaning", "deep cleaning", "move-out cleaning"], "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "note": "Primary homepage, services page and contact-booking page confirm advertised cleaning types, phone and named service cities. No office address established. Weekend-hours wording differs between pages, so hours are not adopted. No review/photo reuse, chemical-safety claims, credentials, guarantee or availability endorsement. Sources https://www.larascleaning.us/, /services.html and /contact---booking.html."}'::jsonb,'Individually sourced relaunch addition; primary-site desk check only','https://www.larascleaning.us/');
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.larascleaning.us/',array['identity','public phone','website','advertised services','advertised service area'],array['Mountain House','Tracy','Lathrop','Manteca'],array['house cleaning','recurring cleaning','deep cleaning','move-out cleaning'],'First-party website desk check only. No owner confirmation, credential validation, availability check or quality endorsement. Primary homepage, services page and contact-booking page confirm advertised cleaning types, phone and named service cities. No office address established. Weekend-hours wording differs between pages, so hours are not adopted. No review/photo reuse, chemical-safety claims, credentials, guarantee or availability endorsement. Sources https://www.larascleaning.us/, /services.html and /contact---booking.html.');
